// Reader for ART's cache-info file (art/odrefresh/CacheInfo.xsd), the subset
// of the XSD-generated C++ API that libart uses (mark_compact.cc reads the
// cached system properties). On Android this header is generated by xsdc
// ("art-apex-cache-info"); Andruna has no xsdc, so it is written here on
// top of tinyxml2.

#pragma once

#include <optional>
#include <string>
#include <vector>

#include <tinyxml2.h>

namespace com {
namespace android {
namespace art {

class KeyValuePair {
 public:
  KeyValuePair(std::string k, std::string v) : k_(std::move(k)), v_(std::move(v)) {}
  const std::string& getK() const { return k_; }
  const std::string& getV() const { return v_; }

 private:
  std::string k_;
  std::string v_;
};

class KeyValuePairList {
 public:
  const std::vector<KeyValuePair>& getItem() const { return item_; }
  std::vector<KeyValuePair> item_;
};

class CacheInfo {
 public:
  const KeyValuePairList* getFirstSystemProperties() const {
    return system_properties_.has_value() ? &*system_properties_ : nullptr;
  }
  std::optional<KeyValuePairList> system_properties_;
};

// Parses the XML text of a cache-info file. Returns nullopt if it is not a
// well-formed <cacheInfo> document.
inline std::optional<CacheInfo> parse(const char* xml) {
  tinyxml2::XMLDocument doc;
  if (doc.Parse(xml) != tinyxml2::XML_SUCCESS) return std::nullopt;
  const tinyxml2::XMLElement* root = doc.FirstChildElement("cacheInfo");
  if (root == nullptr) return std::nullopt;
  CacheInfo info;
  if (const tinyxml2::XMLElement* props = root->FirstChildElement("systemProperties")) {
    KeyValuePairList list;
    for (const tinyxml2::XMLElement* e = props->FirstChildElement("item"); e != nullptr;
         e = e->NextSiblingElement("item")) {
      const char* k = e->Attribute("k");
      const char* v = e->Attribute("v");
      if (k == nullptr || v == nullptr) return std::nullopt;
      list.item_.emplace_back(k, v);
    }
    info.system_properties_ = std::move(list);
  }
  return info;
}

}  // namespace art
}  // namespace android
}  // namespace com
